// Rate Limiter Pattern
// Giới hạn số lượng request/giây để tránh bị 429 Too Many Requests

const input = $input.first().json;
const items = input.items || [$input.first().json];
const RATE_LIMIT = input.rateLimit || 10; // requests per second
const BATCH_SIZE = RATE_LIMIT; // số items mỗi batch

// Chia items thành các batch
const batches = [];
for (let i = 0; i < items.length; i += BATCH_SIZE) {
  batches.push({
    batch_index: batches.length,
    total_batches: Math.ceil(items.length / BATCH_SIZE),
    items: items.slice(i, i + BATCH_SIZE),
    delay_ms: batches.length * 1000 // delay tăng dần theo batch
  });
}

console.log(`Total items: ${items.length}`);
console.log(`Batch size: ${BATCH_SIZE}`);
console.log(`Total batches: ${batches.length}`);

// Trả về batch đầu tiên, các batch sau sẽ được xử lý qua Loop
return [{ json: batches[0] }];

// Check còn batch nào không
const currentBatch = $input.first().json;
const allBatches = $('Split into Batches').all()[0].json;

const nextBatchIndex = currentBatch.batch_index + 1;
const hasNext = nextBatchIndex < allBatches.total_batches;

return [{
  json: {
    has_more: hasNext,
    next_batch_index: nextBatchIndex,
    total_batches: allBatches.total_batches,
    current_progress: `${currentBatch.batch_index + 1}/${allBatches.total_batches}`
  }
}];
